{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.example/protocol/schemas/canonical-transcript-v1.schema.json",
  "title": "Gantry canonical logical-session transcript v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "protocol": { "$ref": "#/$defs/version" },
    "turns": {
      "type": "array",
      "items": { "$ref": "#/$defs/turn" }
    }
  },
  "required": ["protocol", "turns"],
  "$defs": {
    "version": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "major": { "const": 1 },
        "minor": { "const": 0 }
      },
      "required": ["major", "minor"]
    },
    "typed_value": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": { "type": "string", "minLength": 1 },
        "value": {}
      },
      "required": ["type", "value"]
    },
    "interpolation_input": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "position": {
          "type": "number",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "type": { "type": "string", "minLength": 1 },
        "value": {}
      },
      "required": ["position", "type", "value"]
    },
    "named_input": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "name": { "type": "string", "minLength": 1 },
        "type": { "type": "string", "minLength": 1 },
        "value": {}
      },
      "required": ["name", "type", "value"]
    },
    "accepted_result": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "kind": { "enum": ["decision", "unit", "value"] },
        "type": { "type": "string", "minLength": 1 },
        "value": {}
      },
      "required": ["kind", "type", "value"]
    },
    "turn": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "accepted_result": { "$ref": "#/$defs/accepted_result" },
        "interpolation_inputs": {
          "type": "array",
          "items": { "$ref": "#/$defs/interpolation_input" }
        },
        "operation_kind": { "enum": ["decide", "prompt"] },
        "rendered_prompt": { "type": "string" },
        "selected_agent": { "type": "string", "minLength": 1 },
        "template_representation": {
          "type": "array",
          "items": { "type": "string" }
        },
        "using_inputs": {
          "type": "array",
          "items": { "$ref": "#/$defs/named_input" }
        }
      },
      "required": [
        "accepted_result",
        "interpolation_inputs",
        "operation_kind",
        "rendered_prompt",
        "selected_agent",
        "template_representation",
        "using_inputs"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.invalid/protocol/persistent-values/v1/schema.json",
  "title": "Gantry persistent-value conformance vectors v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "format": { "const": "gantry.persistent-values-vectors/v1" },
    "original_canonical": { "type": "string" },
    "original_sha256": { "type": "string", "pattern": "^[0-9a-f]{64}$" },
    "updated_canonical": { "type": "string" },
    "updated_sha256": { "type": "string", "pattern": "^[0-9a-f]{64}$" },
    "metrics": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "nesting_depth": { "type": "integer", "minimum": 1 },
        "nodes": { "type": "integer", "minimum": 1 },
        "maximum_string_scalars": { "type": "integer", "minimum": 0 },
        "maximum_list_items": { "type": "integer", "minimum": 0 }
      },
      "required": [
        "nesting_depth",
        "nodes",
        "maximum_string_scalars",
        "maximum_list_items"
      ]
    },
    "deep_nesting": { "type": "integer", "minimum": 1 }
  },
  "required": [
    "format",
    "original_canonical",
    "original_sha256",
    "updated_canonical",
    "updated_sha256",
    "metrics",
    "deep_nesting"
  ]
}

{
  "$id": "https://gantry.example/protocol/schemas/portable-contracts-v1.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "catalog": { "const": "gantry.portable-contracts" },
    "major": { "const": 1 },
    "minor": { "const": 0 },
    "specification_revision": {
      "pattern": "^[0-9a-f]{64}$",
      "type": "string"
    },
    "maximum_directive_integer": {
      "const": "9223372036854775807"
    },
    "identity_kinds": {
      "items": { "$ref": "#/$defs/identityKind" },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    },
    "protocol_families": {
      "items": { "$ref": "#/$defs/protocolFamily" },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    },
    "vocabularies": {
      "items": { "$ref": "#/$defs/vocabulary" },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    },
    "events": {
      "items": { "$ref": "#/$defs/event" },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    },
    "configuration_fields": {
      "items": { "$ref": "#/$defs/configurationField" },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    }
  },
  "required": [
    "catalog",
    "major",
    "minor",
    "specification_revision",
    "maximum_directive_integer",
    "identity_kinds",
    "protocol_families",
    "vocabularies",
    "events",
    "configuration_fields"
  ],
  "$defs": {
    "wireName": {
      "pattern": "^[a-z](?:[a-z_-]*[a-z])?$",
      "type": "string"
    },
    "rustName": {
      "pattern": "^[A-Z][A-Za-z0-9]*$",
      "type": "string"
    },
    "requirements": {
      "items": {
        "pattern": "^GNT-[A-Za-z0-9.-]+$",
        "type": "string"
      },
      "minItems": 1,
      "type": "array",
      "uniqueItems": true
    },
    "namedValue": {
      "additionalProperties": false,
      "properties": {
        "wire": { "$ref": "#/$defs/wireName" },
        "rust": { "$ref": "#/$defs/rustName" }
      },
      "required": ["wire", "rust"],
      "type": "object"
    },
    "identityKind": {
      "additionalProperties": false,
      "properties": {
        "wire": { "$ref": "#/$defs/wireName" },
        "rust": { "$ref": "#/$defs/rustName" },
        "origin": {
          "enum": ["derived", "fresh", "fresh-or-derived", "storage"]
        },
        "requirements": { "$ref": "#/$defs/requirements" }
      },
      "required": ["wire", "rust", "origin", "requirements"],
      "type": "object"
    },
    "protocolFamily": {
      "additionalProperties": false,
      "properties": {
        "wire": { "$ref": "#/$defs/wireName" },
        "rust": { "$ref": "#/$defs/rustName" },
        "major": {
          "maximum": 9007199254740991,
          "minimum": 0,
          "type": "integer"
        },
        "minor": {
          "maximum": 9007199254740991,
          "minimum": 0,
          "type": "integer"
        },
        "requirements": { "$ref": "#/$defs/requirements" }
      },
      "required": ["wire", "rust", "major", "minor", "requirements"],
      "type": "object"
    },
    "vocabulary": {
      "additionalProperties": false,
      "properties": {
        "name": { "$ref": "#/$defs/wireName" },
        "rust": { "$ref": "#/$defs/rustName" },
        "values": {
          "items": { "$ref": "#/$defs/namedValue" },
          "minItems": 1,
          "type": "array",
          "uniqueItems": true
        },
        "requirements": { "$ref": "#/$defs/requirements" }
      },
      "required": ["name", "rust", "values", "requirements"],
      "type": "object"
    },
    "event": {
      "additionalProperties": false,
      "properties": {
        "wire": { "$ref": "#/$defs/wireName" },
        "rust": { "$ref": "#/$defs/rustName" },
        "layer": { "enum": ["logical", "physical"] },
        "requirements": { "$ref": "#/$defs/requirements" }
      },
      "required": ["wire", "rust", "layer", "requirements"],
      "type": "object"
    },
    "nullableString": {
      "type": ["string", "null"]
    },
    "configurationField": {
      "additionalProperties": false,
      "properties": {
        "wire": { "$ref": "#/$defs/wireName" },
        "rust": { "$ref": "#/$defs/rustName" },
        "class": {
          "enum": [
            "activity-policy",
            "durably-mutable",
            "identity-bound",
            "integration-owned",
            "scheduling-only"
          ]
        },
        "default": { "$ref": "#/$defs/nullableString" },
        "zero_allowed": { "type": ["boolean", "null"] },
        "maximum": { "$ref": "#/$defs/nullableString" },
        "requirements": { "$ref": "#/$defs/requirements" }
      },
      "required": [
        "wire",
        "rust",
        "class",
        "default",
        "zero_allowed",
        "maximum",
        "requirements"
      ],
      "type": "object"
    }
  },
  "title": "Gantry v1 portable contract catalog input",
  "type": "object"
}

{
  "$id": "https://gantry.example/protocol/schemas/profile-catalog-v1.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "catalog": { "const": "gantry.profiles" },
    "major": { "const": 1 },
    "minor": { "const": 0 },
    "profiles": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "name": { "pattern": "^[a-z]+(?:-[a-z]+)*$", "type": "string" },
          "requires": {
            "items": { "pattern": "^[a-z]+(?:-[a-z]+)*$", "type": "string" },
            "type": "array",
            "uniqueItems": true
          },
          "rust_name": { "pattern": "^[A-Z][A-Za-z0-9]*$", "type": "string" }
        },
        "required": ["name", "requires", "rust_name"],
        "type": "object"
      },
      "minItems": 1,
      "type": "array"
    }
  },
  "required": ["catalog", "major", "minor", "profiles"],
  "title": "Gantry v1 profile catalog input",
  "type": "object"
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://gantry.invalid/protocol/value-kernel/v1/schema.json",
  "title": "Gantry value-kernel conformance vectors v1",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "format": { "const": "gantry.value-kernel-vectors/v1" },
    "canonical_input": { "type": "string" },
    "canonical_output": { "type": "string" },
    "canonical_sha256": { "type": "string", "pattern": "^[0-9a-f]{64}$" },
    "rfc8785_input": { "type": "string" },
    "rfc8785_output": { "type": "string" },
    "float_cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "input": { "type": "string" },
          "canonical": { "type": "string" }
        },
        "required": ["input", "canonical"]
      }
    },
    "rejected_floats": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string" }
    },
    "schema_cases": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "schema": { "type": "string" },
          "valid": {
            "type": "array",
            "minItems": 1,
            "items": { "type": "string" }
          },
          "invalid": {
            "type": "array",
            "minItems": 1,
            "items": { "type": "string" }
          }
        },
        "required": ["schema", "valid", "invalid"]
      }
    },
    "integer_equivalents": {
      "type": "array",
      "minItems": 1,
      "items": { "type": "string" }
    },
    "invalid_json": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "input": { "type": "string" },
          "category": {
            "enum": ["duplicate-member", "trailing-data", "unpaired-surrogate"]
          }
        },
        "required": ["input", "category"]
      }
    }
  },
  "required": [
    "format",
    "canonical_input",
    "canonical_output",
    "canonical_sha256",
    "rfc8785_input",
    "rfc8785_output",
    "float_cases",
    "rejected_floats",
    "schema_cases",
    "integer_equivalents",
    "invalid_json"
  ]
}
